-- <auto-generated/> canonical Lua accessor for ComplexShowcase
local GD = require("gd")

-- 表句柄：模块加载时取一次（原生固定槽位引用，跨加载有效）
local _tbl = GD.FindTable("ComplexShowcase")
-- 稀疏 i18n 表句柄：按 i18n 世代**记忆**。
-- 用 GD.I18nGen() 而不是「nil 才重试」：切回主语言后句柄会重新变成
-- 不可解析，只按 nil 重试会把失效句柄一直用下去（原生 check_tbl 直接报错）。
local _i18nTbl, _i18nGen = nil, nil
local function i18n_table()
    local g = GD.I18nGen()
    if g ~= _i18nGen then
        _i18nTbl = GD.FindTableI18n("ComplexShowcase_i18n")
        _i18nGen = g
    end
    return _i18nTbl
end

-- 元表工厂：字段名 → 读取函数（分发表一次性构建，所有行共享同一元表）
local function make_meta(readers)
    return { __index = function(self, key)
        local fn = readers[key]
        if fn then return fn(self) end
    end }
end

-- 数组视图元表（**惰性视图**：不建 Lua 表、稳态零分配）
local ArrayMeta = {
    __len   = function(v) return GD.ArrLen(v) end,
    __index = function(v, i) return GD.ArrAt(v, i) end,
    __pairs = ipairs,   -- 契约测试要求 for _, v in pairs(tags) 可用
}

local WorldPositionMeta = make_meta({
    X = function(s) return GD.F64(s, 4) end,
    Y = function(s) return GD.F64(s, 6) end,
    Z = function(s) return GD.F64(s, 8) end,
    Space = function(s) return GD.I8(s, 10) end,
    IsPrecise = function(s) return GD.I8(s, 12) ~= 0 end,
})

local RewardDefinitionMeta = make_meta({
    Kind = function(s) return GD.I8(s, 4) end,
    ItemIds = function(s) return GD.Arr(s, 6, "i32", ArrayMeta) end,
    Amounts = function(s) return GD.Arr(s, 8, "i32", ArrayMeta) end,
    Chance = function(s) return GD.F32(s, 10) end,
    Bounds = function(s) return GD.Struct(s, 12, RewardBoundsMeta) end,
})

local RewardBoundsMeta = make_meta({
    Min = function(s) return GD.I32(s, 4) end,
    Max = function(s) return GD.I32(s, 6) end,
    Guaranteed = function(s) return GD.I8(s, 8) ~= 0 end,
})

-- ⚠️ 本表是**定宽布局**：下面全是字面量偏移读（无 vtable 走查）。
--    偏移由导出期 `probe_row_layout` 算出，是表级常量；改变 schema 必须重新导出。
-- 行访问器元表（self = 行 userdata）
local RowMeta = make_meta({
    Id = function(s) return GD.I32Off(s, 4) end,
    CodeName = function(s) return GD.StrOff(s, 8) end,
    Weight = function(s) return GD.F32Off(s, 12) end,
    PreciseValue = function(s) return GD.F64Off(s, 16) end,
    IsEnabled = function(s) return GD.I8Off(s, 24) ~= 0 end,
    DisplayName = function(s) local v = GD.I18nStr(i18n_table(), s, 6) return v ~= nil and v or GD.StrOff(s, 28) end,
    Rarity = function(s) return GD.I8Off(s, 32) end,
    ItemTypeId = function(s) return GD.I32Off(s, 36) end,
    ItemType = function(s) return Config.ItemType.ByID(GD.I32Off(s, 36)) end,
    Position = function(s) return GD.StructOff(s, 40, WorldPositionMeta) end,
    Reward = function(s) return GD.StructOff(s, 44, RewardDefinitionMeta) end,
    IntValues = function(s) return GD.ArrOff(s, 48, "i32", ArrayMeta) end,
    LongValues = function(s) return GD.ArrOff(s, 52, "i64", ArrayMeta) end,
    Ratios = function(s) return GD.ArrOff(s, 56, "f32", ArrayMeta) end,
    Precisions = function(s) return GD.ArrOff(s, 60, "f64", ArrayMeta) end,
    Flags = function(s) return GD.ArrOff(s, 64, "b", ArrayMeta) end,
    Aliases = function(s) return GD.ArrOff(s, 68, "s", ArrayMeta) end,
    Rarities = function(s) return GD.ArrOff(s, 72, "i8", ArrayMeta) end,
    SpawnPoints = function(s) error("[Config] Lua 不支持 SpawnPoints（vector<WorldPosition>）：原生 gd 模块没有 record 元素的 tag") end,
    RewardTiers = function(s) error("[Config] Lua 不支持 RewardTiers（vector<RewardDefinition>）：原生 gd 模块没有 record 元素的 tag") end,
})

-- 公开 API（纯函数，无状态）
local M = {}
function M.Count() return GD.Count(_tbl) end
function M.ByID(id) return GD.ByID(_tbl, id, RowMeta) end
function M.ByIndex(i) return GD.ByIndex(_tbl, i, RowMeta) end
-- 原生 codeName 查询：FNV-1a 64 桶表 + 按字段精确字符串确认
function M.ByCodeName(codeName) return GD.ByCodeName(_tbl, 1, codeName, RowMeta) end
return M
